 81→  ret = esp_setup_irq_with_flags(source,
 82→                                ESP_INTR_FLAG_LEVEL1 | ESP_INTR_FLAG_IRAM,
 83→                                riscv_smp_call_handler, NULL);
 84→  if (ret < 0)
 85→    {
 86→      return ret;
 87→    }
 88→
 89→  up_enable_irq(ESP_SOURCE2IRQ(source));
 90→  return OK;
 91→}
