 93→static int esp_smp_secondary_initialize(void)
 94→{
 95→  extern esp_system_init_fn_t _esp_system_init_fn_array_start;
 96→  extern esp_system_init_fn_t _esp_system_init_fn_array_end;
 97→  FAR esp_system_init_fn_t *fn;
 98→
 99→  /* Run only CPU1's secondary hooks.  The CORE hooks and constructors have
100→   * already run on CPU0; re-entering __esp_start() would clear shared BSS.
101→   */
102→
103→  for (fn = &_esp_system_init_fn_array_start;
104→       fn < &_esp_system_init_fn_array_end; fn++)
105→    {
106→      if (fn->stage == ESP_SYSTEM_INIT_STAGE_SECONDARY &&
107→          (fn->cores & (1 << 1)) != 0 && fn->fn() != ESP_OK)
108→        {
109→          return -EIO;
110→        }
111→    }
112→
113→  return OK;
