120→int IRAM_ATTR riscv_smp_call_handler(int irq, FAR void *context,
121→                                    FAR void *arg)
122→{
123→  FAR struct tcb_s *tcb;
124→  int cpu = this_cpu();
125→
126→  /* Clear before processing requests so a new request can reassert the IPI.
127→   * P4 has peripheral cross-core interrupts, not CLINT/MSIP interrupts.
128→   */
129→
130→  crosscore_int_ll_clear_interrupt(cpu);
131→  UP_DMB();
