133→
134→  tcb = current_task(cpu);
135→  riscv_savecontext(tcb);
136→  nxsched_process_delivered(cpu);
137→  tcb = current_task(cpu);
138→  riscv_restorecontext(tcb);
139→  return OK;
140→}
