static bool g_ipi_initialized[CONFIG_SMP_NCPUS];
static volatile bool g_secondary_ready[CONFIG_SMP_NCPUS];

struct esp_ipc_call_s
{
  esp_ipc_func_t func;
  void *arg;
};

struct esp_ipc_async_call_s
{
  struct smp_call_data_s data;
  esp_ipc_func_t func;
  void *arg;
  volatile uint32_t pending;
};

static int esp_ipc_call_adapter(void *arg)
{
  struct esp_ipc_call_s *call = arg;

  call->func(call->arg);
  return OK;
}

static int IRAM_ATTR esp_ipc_call_async_adapter(void *arg)
{
  struct esp_ipc_async_call_s *call = arg;

  call->func(call->arg);
  call->func = NULL;
  call->arg = NULL;
  __atomic_store_n(&call->pending, 0, __ATOMIC_RELEASE);
  return OK;
}

static struct esp_ipc_async_call_s
  g_ipc_async_calls[CONFIG_SMP_NCPUS];

static esp_err_t esp_ipc_call_internal(uint32_t cpu_id,
                                       esp_ipc_func_t func, void *arg)
{
  struct esp_ipc_call_s call;
  int ret;

  if (cpu_id >= CONFIG_SMP_NCPUS || func == NULL)
    {
      return ESP_ERR_INVALID_ARG;
    }

  call.func = func;
  call.arg = arg;
  ret = nxsched_smp_call_single(cpu_id, esp_ipc_call_adapter, &call);

  return ret < 0 ? ESP_FAIL : ESP_OK;
}

esp_err_t esp_ipc_call(uint32_t cpu_id, esp_ipc_func_t func, void *arg)
{
  return esp_ipc_call_internal(cpu_id, func, arg);
}

esp_err_t esp_ipc_call_blocking(uint32_t cpu_id, esp_ipc_func_t func,
                                void *arg)
{
  return esp_ipc_call_internal(cpu_id, func, arg);
}

esp_err_t esp_ipc_call_nonblocking(uint32_t cpu_id, esp_ipc_func_t func,
                                   void *arg)
{
  struct esp_ipc_async_call_s *call;
  int ret;

  if (cpu_id >= CONFIG_SMP_NCPUS || func == NULL)
    {
      return ESP_ERR_INVALID_ARG;
    }

  call = &g_ipc_async_calls[cpu_id];
  if (!esp_cpu_compare_and_set(&call->pending, 0, 1))
    {
      return ESP_FAIL;
    }

  call->func = func;
  call->arg = arg;
  nxsched_smp_call_init(&call->data, esp_ipc_call_async_adapter, call);

  ret = nxsched_smp_call_single_async(cpu_id, &call->data);
  if (ret < 0)
    {
      call->func = NULL;
      call->arg = NULL;
      __atomic_store_n(&call->pending, 0, __ATOMIC_RELEASE);
      return ESP_FAIL;
    }

  return ESP_OK;
}

void esp_ipi_send(int cpu)
{
  DEBUGASSERT(cpu >= 0 && cpu < CONFIG_SMP_NCPUS);
  crosscore_int_ll_trigger_interrupt(cpu);
}

void esp_ipi_clear(int cpu)
{
  DEBUGASSERT(cpu >= 0 && cpu < CONFIG_SMP_NCPUS);
  crosscore_int_ll_clear_interrupt(cpu);
}

void esp_ipi_wait(int cpu)
{
  DEBUGASSERT(cpu > 0 && cpu < CONFIG_SMP_NCPUS);

  while (crosscore_int_ll_get_state(cpu) == 0)
    {
      __asm__ __volatile__("nop");
    }

  esp_ipi_clear(cpu);
}

void esp_ipi_initialize(int cpu)
{
  int irq;
  int source;
  int cpuint;

  DEBUGASSERT(cpu >= 0 && cpu < CONFIG_SMP_NCPUS);

  if (g_ipi_initialized[cpu])
    {
      return;
    }

  if (cpu == 0)
    {
      esp_ipi_clear(cpu);
    }

  source = cpu == 0 ? SYS_CPU_INTR_FROM_CPU_0_SOURCE :
                      SYS_CPU_INTR_FROM_CPU_1_SOURCE;
  irq = cpu == 0 ? ESP_IRQ_FROM_CPU_INTR0 : ESP_IRQ_FROM_CPU_INTR1;

  cpuint = esp_setup_irq(source, ESP_IRQ_PRIORITY_1,
                         ESP_IRQ_TRIGGER_LEVEL,
                         riscv_smp_call_handler, NULL);
  DEBUGASSERT(cpuint >= 0);

  g_ipi_initialized[cpu] = true;
  up_enable_irq(irq);
}

void IRAM_ATTR esp_smp_start_secondary(int cpu)
{
  DEBUGASSERT(cpu == 1);

  ets_set_appcpu_boot_addr((uint32_t)esp_smp_secondary_start);
  __asm__ __volatile__("fence rw, rw" ::: "memory");
  cpu_utility_ll_enable_clock_and_reset_app_cpu();
  cpu_utility_ll_enable_clock_and_reset_app_cpu_int_matrix();
  esp_cpu_unstall(cpu);
}

void IRAM_ATTR esp_smp_secondary_c(void)
{
#ifdef CONFIG_ARCH_FPU
  riscv_fpuconfig();
#endif
  ets_set_appcpu_boot_addr(0);
  esp_cpu_intr_set_ivt_addr(&_vector_table);
  esp_cpu_intr_set_mtvt_addr(&_mtvt_table);
  __atomic_store_n(&g_secondary_ready[1], true, __ATOMIC_RELEASE);
  riscv_cpu_boot(1);
  __builtin_unreachable();
}

void IRAM_ATTR __attribute__((naked, noinline)) esp_smp_secondary_start(void)
{
  __asm__ __volatile__(
    ".option push\n"
    ".option norelax\n"
    "la gp, __global_pointer$\n"
    "la t0, g_idle_topstack\n"
    "lw sp, 0(t0)\n"
    "andi sp, sp, -16\n"
    ".option pop\n"
    "tail esp_smp_secondary_c\n");
}

